#include <stdio.h>

int main(void) {
    int bowls[8];
    int n;

    if (scanf("%d", &n) != 1) {
        return 1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bowls[i]) != 1) {
            return 1;
        }
    }

    int *p = bowls;
    for (int i = 0; i + 1 < n; i++) {
        printf("第 %d 只和第 %d 只差 %d\n", i, i + 1, *(p + 1) - *p);
        p = p + 1;
    }
    return 0;
}
